-- Onboarding Specialist: option order shuffled per question so the correct position is no longer a fixed rotation.
-- Only the server-side answer keys change; no submissions exist for this program yet (checked in the guard below).
do $$ begin if exists(select 1 from public.learning_practice_submissions s join public.learning_activity_catalog a on a.id=s.activity_id where a.route_key='onboarding') then raise exception 'ONBOARDING_SUBMISSIONS_EXIST'; end if; end $$;
update codezero_private.position_assessments m set correct_answers=(select array_agg(c::integer order by o) from regexp_split_to_table(v.a,'') with ordinality x(c,o))
